  assert.throws(() => crearVentaRegistrada({ ...VENTA, almacen: "ALM-01" }), TypeError);
  assert.throws(() => crearStockAjustado({ id: "S-1", fecha: "2026-11-01", sku: "X", delta: 1, motivo: "m", canal: "web" }), TypeError);
});
